"use client";

import * as React from "react";
import { createNodeFromContent, type Content, type Editor } from "@tiptap/core";
import { useEmojiStore, useEmojiTypeahead, type EmojiTypeahead, type EmojiTypeaheadOptions, type ShortcodeCompletion } from "emoji-components";
import { emojiTypeahead } from "@/lib/emoji-prosemirror";

export type TiptapEmojiTypeaheadOptions = EmojiTypeaheadOptions & {
  content?: (text: string, suggestion: ShortcodeCompletion) => Content;
};

export function useTiptapEmojiTypeahead(editor: Editor | null, { content, onSelect, insert, limit, matchBy, order, columns }: TiptapEmojiTypeaheadOptions = {}): EmojiTypeahead {
  const store = useEmojiStore();
  const id = React.useId();
  const latest = React.useRef({ content, onSelect });
  React.useEffect(() => {
    latest.current = { content, onSelect };
  });
  const { plugin, key, suggestions, anchor } = React.useMemo(
    () =>
      emojiTypeahead(store, {
        id,
        insert,
        limit,
        matchBy,
        order,
        columns,
        onSelect: (selection) => latest.current.onSelect?.(selection),
        content(text, suggestion, schema) {
          const replacement = latest.current.content?.(text, suggestion) ?? `${text} `;
          return typeof replacement === "string" ? replacement : createNodeFromContent(replacement, schema);
        },
      }),
    [store, id, insert, limit, matchBy, order, columns],
  );
  React.useEffect(() => {
    if (!editor || editor.isDestroyed) return;
    editor.registerPlugin(plugin, (p, plugins) => [p, ...plugins]);
    return () => void (editor.isDestroyed || editor.unregisterPlugin(key));
  }, [editor, plugin, key]);
  return useEmojiTypeahead(suggestions, { anchor });
}

import type { Editor } from "@tiptap/react";
import type { EmojiTypeaheadOptions } from "emoji-components";
import { useTiptapEmojiTypeahead } from "@/hooks/use-emoji-tiptap";
import { EmojiSuggestions, type EmojiSuggestionsProps } from "@/components/ui/emoji-suggestions";
import { emojiContent } from "./emoji-node";

export function EmojiSuggestionMenu({ editor, className, side, ...options }: EmojiSuggestionsProps & EmojiTypeaheadOptions & { editor: Editor | null }) {
  const emoji = useTiptapEmojiTypeahead(editor, {
    ...options,
    content: (text, { record, shortcode }) => (record.imageUrl ? emojiContent({ unified: record.unified, shortcode, text: null }) : `${text} `),
  });
  return <EmojiSuggestions {...emoji} className={className} side={side} />;
}

import { InputRule, Node, NodeViewWrapper, ReactNodeViewRenderer, mergeAttributes, type NodeViewProps } from "@tiptap/react";
import { Emoji, type EmojiStore } from "emoji-components";

export type EmojiNodeAttrs = {
  unified: string;
  shortcode: string;
  text: string | null;
};

export type EmojiNodeOptions = {
  store: EmojiStore | null;
};

declare module "@tiptap/react" {
  interface Commands<ReturnType> {
    emoji: { insertEmoji: (attrs: EmojiNodeAttrs) => ReturnType };
  }
}

export function emojiAttrs(store: EmojiStore, idOrShortcode: string): EmojiNodeAttrs | null {
  const record = store.get(idOrShortcode) ?? store.fromShortcode(idOrShortcode);
  if (!record) return null;
  const unified = record.imageUrl ? record.unified : store.withSkinTone(record.unified);
  const text = record.imageUrl ? null : String.fromCodePoint(...unified.split("-").map((hex) => parseInt(hex, 16)));
  return { unified, shortcode: record.shortcodes[0] ?? record.unified, text };
}

export const emojiContent = (attrs: EmojiNodeAttrs) => [
  { type: "emoji", attrs },
  { type: "text", text: " " },
];

function EmojiView({ node }: NodeViewProps) {
  const { unified } = node.attrs as EmojiNodeAttrs;
  return (
    <NodeViewWrapper as="span" className="inline-block align-[-0.2em]" data-emoji-node="">
      <Emoji emoji={unified} size={20} className="inline-block size-[1.25em] leading-none" />
    </NodeViewWrapper>
  );
}

export const EmojiNode = Node.create<EmojiNodeOptions>({
  name: "emoji",
  group: "inline",
  inline: true,
  atom: true,
  selectable: false,
  addOptions: () => ({ store: null }),

  addAttributes: () => ({
    unified: { default: null, parseHTML: (el) => el.getAttribute("data-unified") },
    shortcode: { default: null, parseHTML: (el) => el.getAttribute("data-shortcode") },
    text: { default: null, parseHTML: (el) => el.getAttribute("data-text") },
  }),

  parseHTML: () => [{ tag: "span[data-emoji-node]" }],

  renderHTML({ node, HTMLAttributes }) {
    const { unified, shortcode, text } = node.attrs as EmojiNodeAttrs;
    return ["span", mergeAttributes(HTMLAttributes, { "data-emoji-node": "", "data-unified": unified, "data-shortcode": shortcode, "data-text": text }), text ?? `:${shortcode}:`];
  },

  renderText: ({ node }) => {
    const { shortcode, text } = node.attrs as EmojiNodeAttrs;
    return text ?? `:${shortcode}:`;
  },

  addNodeView() {
    return ReactNodeViewRenderer(EmojiView, { as: "span" });
  },

  addCommands() {
    return {
      insertEmoji:
        (attrs) =>
        ({ commands }) =>
          commands.insertContent(emojiContent(attrs)),
    };
  },

  addInputRules() {
    const { store } = this.options;
    return [
      new InputRule({
        find: /:([a-z0-9_+'-]+):$/i,
        handler: ({ state, range, match }) => {
          const attrs = store ? emojiAttrs(store, match[1]!) : null;
          if (!attrs) return null;
          state.tr.replaceWith(range.from, range.to, this.type.create(attrs));
        },
      }),
    ];
  },
});
